<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRouter } from 'vue-router'
import StatusNotice from '../components/StatusNotice.vue'
import { adminRedPacketApi, adminSession, isApiRequestError, type AdminRedPacketLifecycle, type AdminRedPacketResource } from '../services'
type Kind = 'pause'|'resume'|'terminate'
const router = useRouter(); const items=ref<AdminRedPacketResource[]>([]); const selected=ref<AdminRedPacketResource>(); const loading=ref(true); const saving=ref(false); const error=ref(''); const notice=ref(''); const action=ref<Kind>(); const reason=ref(''); const filters=reactive({status:'',keyword:''})
const canManage=computed(()=>adminSession.hasPermission('redpacket.manage')); const canTerminate=computed(()=>adminSession.hasPermission('redpacket.terminate'))
function label(value:string){return ({ACTIVE:'进行中',PAUSED_BY_RISK:'风控暂停',TERMINATED_BY_PLATFORM:'平台终止'} as Record<string,string>)[value]??value}
function message(caught:unknown){if(isApiRequestError(caught)){if(caught.status===401)adminSession.clear();return caught.message}return '风险活动暂时无法加载'}
async function load(){loading.value=true;error.value='';try{const page=await adminRedPacketApi.campaigns({status:filters.status||undefined,keyword:filters.keyword||undefined,sort:'updatedAt:desc'});items.value=page.items.filter(i=>['ACTIVE','PAUSED_BY_RISK','TERMINATED_BY_PLATFORM'].includes(i.status))}catch(caught){error.value=message(caught)}finally{loading.value=false}}
function open(kind:Kind,item:AdminRedPacketResource){if((kind==='terminate'&&!canTerminate.value)||(kind!=='terminate'&&!canManage.value))return;selected.value=item;action.value=kind;reason.value=''}
async function submit(){if(!selected.value||!action.value||(action.value==='terminate'&&!reason.value.trim()))return;saving.value=true;error.value='';try{const body:AdminRedPacketLifecycle={reason:reason.value.trim()||undefined,expectedVersion:selected.value.version};const key=`r23-${action.value}-${selected.value.id}-${selected.value.version}-${Date.now().toString(36)}`;const result=action.value==='pause'?await adminRedPacketApi.pause(selected.value.id,body,key):action.value==='resume'?await adminRedPacketApi.resume(selected.value.id,body,key):await adminRedPacketApi.terminate(selected.value.id,{...body,reason:reason.value.trim()},key);items.value=items.value.map(i=>i.id===selected.value?.id?result as AdminRedPacketResource:i);notice.value=`${action.value==='pause'?'平台暂停':action.value==='resume'?'恢复':'平台终止'}已提交并写入服务端审计。`;selected.value=undefined;action.value=undefined}catch(caught){error.value=message(caught)}finally{saving.value=false}}
onMounted(()=>{void load()})
</script>
<template><article class="page red-packet-risk-page"><header class="page-heading"><div><div class="eyebrow">红包运营 / 风险事件</div><h1>红包风险事件</h1><p>仅对服务端返回的活动执行平台暂停、恢复和终止；每次处置绑定当前版本、原因、幂等键和审计。</p></div><button class="ghost-button" :disabled="loading" @click="load">刷新</button></header><StatusNotice v-if="error" tone="danger" title="风险数据或操作失败" :detail="error"/><StatusNotice v-if="notice" tone="success" title="风险处置结果" :detail="notice"/><form class="card risk-filter" @submit.prevent="load"><label class="field"><span class="field-label">状态</span><select v-model="filters.status" class="input"><option value="">全部风险相关活动</option><option value="ACTIVE">进行中</option><option value="PAUSED_BY_RISK">风控暂停</option><option value="TERMINATED_BY_PLATFORM">平台终止</option></select></label><label class="field"><span class="field-label">关键词</span><input v-model="filters.keyword" class="input" maxlength="100" placeholder="活动或内容 ID"/></label><button class="primary-button" :disabled="loading">查询</button></form><section class="card risk-table-card"><div v-if="loading" class="loading-state">正在加载风险活动…</div><div v-else-if="!items.length" class="empty-state"><h2>暂无可处置的红包活动</h2><p>当前筛选没有进行中、风控暂停或平台终止的活动。</p></div><table v-else class="data-table"><thead><tr><th>活动</th><th>状态</th><th>剩余库存</th><th>服务端版本</th><th>风险处置</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td><strong>{{ item.id }}</strong><small>内容 {{ item.contentId }}</small></td><td><span class="status-chip" :data-status="item.status">{{ label(item.status) }}</span></td><td>{{ item.remainingCount }} / {{ item.totalCount }}</td><td>v{{ item.version }}</td><td class="button-row"><button v-if="item.status==='ACTIVE'" class="secondary-button" :disabled="!canManage" @click="open('pause',item)">平台暂停</button><button v-if="item.status==='PAUSED_BY_RISK'" class="secondary-button" :disabled="!canManage" @click="open('resume',item)">恢复</button><button v-if="item.status!=='TERMINATED_BY_PLATFORM'" class="danger-button" :disabled="!canTerminate" @click="open('terminate',item)">终止且不退款</button><button class="ghost-button" @click="router.push({name:'ADM-RP-002',params:{id:item.id}})">查看证据</button></td></tr></tbody></table></section><div v-if="selected&&action" class="modal-backdrop" @click.self="!saving&&(selected=undefined)"><section class="modal" role="dialog" aria-modal="true"><header class="modal-header"><div><h2>{{ action==='pause'?'确认平台暂停':action==='resume'?'确认恢复活动':'确认平台终止' }}</h2><p>目标活动 {{ selected.id }} · 服务端版本 v{{ selected.version }}。操作结果由服务端状态机再次复核。</p></div><button class="icon-button" :disabled="saving" @click="selected=undefined">×</button></header><label class="field"><span class="field-label">处置原因{{ action==='terminate'?'（必填）':'（可选）' }}</span><textarea v-model="reason" class="input" maxlength="2000" placeholder="记录风险证据编号与处置依据；不要输入不必要的个人信息。"/></label><StatusNotice tone="warning" title="提交前检查" :detail="action==='terminate'?'终止且不退款不可直接恢复；请确认原因和影响。':'提交期间将锁定当前操作；409 冲突不会自动重试。'"/><footer class="modal-footer"><button class="ghost-button" :disabled="saving" @click="selected=undefined">取消</button><button :class="action==='terminate'?'danger-button':'primary-button'" :disabled="saving||(action==='terminate'&&!reason.trim())" @click="submit">{{ saving?'提交中…':'确认提交' }}</button></footer></section></div></article></template>
